"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { useFormik } from "formik";
import * as Yup from "yup";
import axiosInstance from "@/utils/axiosInstance";
import Select from "react-select";
import { useCategories } from "@/hooks/useCategories"; // Hook to fetch categories

interface ProductData {
  id: number;
  productName: string;
  detail: string;
  price: number;
  weight: number;
  productCategory: string;
  productPictures: { pictureId: number; productPictureUrl: string; position: number }[];
  status: string;
}

const ProductDraftForm = () => {
  const { id } = useParams();
  const router = useRouter();
  const { data: categories } = useCategories(1, 100, ""); // Fetch all categories (1st page, 100 items)
  
  const [productData, setProductData] = useState<ProductData | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  
  useEffect(() => {
    if (id) {
      console.log("Fetching product data for ID:", id);
  
      axiosInstance
        .get(`/products/${id}`)
        .then((res) => {
          console.log("Fetched product data:", res.data);
          setProductData(res.data);
        })
        .catch((err) => console.error("Error fetching product data:", err));
    } else {
      console.error("Invalid id: Cannot fetch product data.");
    }
  }, [id]);

  // Form validation schema
  const validationSchema = Yup.object({
    productName: Yup.string()
      .min(3, "Must be at least 3 words")
      .notOneOf(["Draft Product"], "Cannot be 'Draft Product'"),
    detail: Yup.string()
      .min(3, "Must be at least 3 words")
      .notOneOf(["This is a draft product"], "Cannot be 'This is a draft product'"),
    price: Yup.number().moreThan(0, "Price must be greater than 0").required("Required"),
    weight: Yup.number().moreThan(0, "Weight must be greater than 0").required("Required"),
    productCategory: Yup.string().required("Category is required"),
    productPictures: Yup.array()
    .nullable()
    .default([])
    .test("at-least-one-image", "At least one image is required", (value) => 
      Array.isArray(value) && value.some((pic) => pic !== null)
    ),
  });

  const formik = useFormik({
    initialValues: {
      productName: productData?.productName || "",
      detail: productData?.detail || "",
      price: productData?.price || "",
      weight: productData?.weight || "",
      productCategory: productData?.productCategory || "",
      productPictures: [null, null, null], // Three slots for images
    },
    enableReinitialize: true,
    validationSchema,
    onSubmit: async (values) => {
      setIsSubmitting(true);
      try {
        await axiosInstance.patch(`/products/${id}/create`, values);
        router.push("/dashboard/admin/products");
      } catch (error) {
        console.error("Error creating product:", error);
      } finally {
        setIsSubmitting(false);
      }
    },
  });

  const handleSaveDraft = async () => {
    await axiosInstance.patch(`/products/${id}/draft`, formik.values);
    router.push("/dashboard/admin/products");
  };

  const handleDeleteDraft = async () => {
    await axiosInstance.delete(`/products/${id}/delete`);
    router.push("/dashboard/admin/products");
  };

  return (
    <div className="p-6 bg-white shadow-md rounded-lg">
      <h2 className="text-3xl font-semibold mb-4">📝 Edit Draft Product</h2>

      <form onSubmit={formik.handleSubmit} className="space-y-4">
        {/* Product Name */}
        <div>
          <label className="block text-gray-700">Product Name</label>
          <input
            type="text"
            className="w-full p-2 border rounded"
            {...formik.getFieldProps("productName")}
          />
          {formik.touched.productName && formik.errors.productName && (
            <div className="text-red-500">{formik.errors.productName}</div>
          )}
        </div>

        {/* Detail */}
        <div>
          <label className="block text-gray-700">Detail</label>
          <textarea
            className="w-full p-2 border rounded"
            {...formik.getFieldProps("detail")}
          />
          {formik.touched.detail && formik.errors.detail && (
            <div className="text-red-500">{formik.errors.detail}</div>
          )}
        </div>

        {/* Price */}
        <div>
          <label className="block text-gray-700">Price</label>
          <div className="flex items-center">
            <span className="mr-2">Rp.</span>
            <input
              type="number"
              className="w-full p-2 border rounded"
              {...formik.getFieldProps("price")}
            />
          </div>
          {formik.touched.price && formik.errors.price && (
            <div className="text-red-500">{formik.errors.price}</div>
          )}
        </div>

        {/* Weight */}
        <div>
          <label className="block text-gray-700">Weight (gram)</label>
          <div className="flex items-center">
            <input
              type="number"
              className="w-full p-2 border rounded"
              {...formik.getFieldProps("weight")}
            />
            <span className="ml-2">gram</span>
          </div>
          {formik.touched.weight && formik.errors.weight && (
            <div className="text-red-500">{formik.errors.weight}</div>
          )}
        </div>

        {/* Category */}
        <div>
          <label className="block text-gray-700">Category</label>
          <Select
            options={categories?.content.map((cat) => ({
              value: cat.categoryName,
              label: cat.categoryName,
            }))}
            onChange={(selectedOption: { value: string } | null) =>
              formik.setFieldValue("productCategory", selectedOption?.value)
            }
            isSearchable
          />
          {formik.touched.productCategory && formik.errors.productCategory && (
            <div className="text-red-500">{formik.errors.productCategory}</div>
          )}
        </div>

        {/* Product Pictures */}
        <div>
          <label className="block text-gray-700">Product Pictures</label>
          <div className="flex space-x-2">
            {formik.values.productPictures.map((pic, index) => (
              <div key={index} className="relative w-24 h-24 border rounded">
                {pic ? (
                  <button
                    type="button"
                    className="absolute top-0 right-0 bg-red-500 text-white p-1"
                    onClick={() => {
                      let newPics = [...formik.values.productPictures];
                      newPics[index] = null;
                      formik.setFieldValue("productPictures", newPics);
                    }}
                  >
                    ❌
                  </button>
                ) : (
                  <button
                    type="button"
                    className="absolute inset-0 flex items-center justify-center bg-gray-200"
                  >
                    📤 Upload
                  </button>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Buttons */}
        <div className="flex space-x-4">
          <button
            type="submit"
            className="bg-blue-500 text-white px-4 py-2 rounded"
            disabled={isSubmitting || !formik.isValid}
          >
            {isSubmitting ? "Creating..." : "Create Product"}
          </button>
          <button type="button" onClick={handleSaveDraft} className="bg-gray-500 text-white px-4 py-2 rounded">
            Save Draft
          </button>
          <button type="button" onClick={handleDeleteDraft} className="bg-red-500 text-white px-4 py-2 rounded">
            Delete Draft
          </button>
        </div>
      </form>
    </div>
  );
};

export default ProductDraftForm;